import os, signal
killed = []
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    try:
        with open(f'/proc/{pid}/cmdline', 'rb') as f:
            cmd = f.read().replace(b'\x00', b' ').decode(errors='ignore')
        if 'debug2.py' in cmd or 'validate_dicke.py' in cmd:
            os.kill(int(pid), signal.SIGKILL)
            killed.append((pid, cmd.strip()))
    except Exception:
        pass
print("killed:", killed)

